-- Hardening from the pre-landing review of the first three migrations. Every item
-- here is a change to tables that already exist, so it is a new migration: the
-- earlier ones have been applied and must not be edited.

-- ---------------------------------------------------------------------------
-- 1. A client can no longer choose its own generated keys
-- ---------------------------------------------------------------------------
-- With `generated by default`, a signed-in user could INSERT rows with explicit
-- seq/id values equal to the next values of the shared sequence. The sequence
-- does not advance on an explicit insert, so every other user's next insert then
-- hit a duplicate key until the sequence had skipped past all the planted values:
-- one account could break chat and log writes for everybody. `generated always`
-- makes Postgres refuse an explicit value from anyone who has not said
-- OVERRIDING SYSTEM VALUE (the importer never supplies these columns).
alter table public.coach_messages        alter column seq set generated always;
alter table public.workout_chat_messages alter column seq set generated always;
alter table public.analyze_chat_messages alter column seq set generated always;
alter table public.analyze_log_entries   alter column id  set generated always;

-- ---------------------------------------------------------------------------
-- 2. Chat turns carry a client-generated idempotency key
-- ---------------------------------------------------------------------------
-- The old chat blobs were replaced whole, so a retried write was harmless. As rows,
-- a retry after a dropped response would duplicate the turn. The key must be part
-- of a NON-partial unique constraint so PostgREST can upsert on
-- `on_conflict=user_id,client_id` (it cannot infer a partial index). Rows that
-- predate the key get one derived from their seq.
alter table public.coach_messages add column client_id text;
update public.coach_messages set client_id = 'legacy-seq-' || seq where client_id is null;
alter table public.coach_messages alter column client_id set not null;
alter table public.coach_messages add constraint coach_messages_user_client_key unique (user_id, client_id);

alter table public.analyze_chat_messages add column client_id text;
update public.analyze_chat_messages set client_id = 'legacy-seq-' || seq where client_id is null;
alter table public.analyze_chat_messages alter column client_id set not null;
alter table public.analyze_chat_messages
    add constraint analyze_chat_messages_user_client_key unique (user_id, client_id);

update public.workout_chat_messages set client_id = 'legacy-seq-' || seq where client_id is null;
alter table public.workout_chat_messages alter column client_id set not null;
drop index public.idx_workout_chat_client_id;
alter table public.workout_chat_messages
    add constraint workout_chat_messages_user_client_key unique (user_id, client_id);

-- ---------------------------------------------------------------------------
-- 3. Indexes on the columns row-level security and cascades filter by
-- ---------------------------------------------------------------------------
-- Every app read of these tables runs `user_id = auth.uid()` and every account
-- deletion cascades through them; without an index each is a sequential scan, once
-- per deleted user.
create index idx_custom_foods_user                on public.custom_foods (user_id);
create index idx_custom_exercises_user            on public.custom_exercises (user_id);
create index idx_progress_photos_user             on public.progress_photos (user_id, date);
create index idx_hyrox_results_user               on public.hyrox_results (user_id, created_at desc);
create index idx_friends_friend                   on public.friends (friend_id);
create index idx_challenges_creator               on public.challenges (creator_id);
create index idx_challenge_submissions_user       on public.challenge_submissions (user_id);
create index idx_content_reports_reporter         on public.content_reports (reporter_id);
create index idx_content_reports_reported         on public.content_reports (reported_id);
create index idx_ai_reports_user                  on public.ai_reports (user_id);

-- ---------------------------------------------------------------------------
-- 4. Parked import data is erased with its owner
-- ---------------------------------------------------------------------------
-- import_quarantine holds raw legacy payloads (food logs, chat text). Keyed only by
-- the legacy integer it was outside every ON DELETE CASCADE chain, so a deleted
-- account's parked data would have stayed forever.
alter table public.import_quarantine
    add column user_id uuid references public.profiles (id) on delete cascade;
update public.import_quarantine q
   set user_id = (select p.id from public.profiles p where p.legacy_user_id = q.legacy_user_id)
 where q.user_id is null and q.legacy_user_id is not null;
create index idx_import_quarantine_user on public.import_quarantine (user_id);

-- ---------------------------------------------------------------------------
-- 5. The coaching profile cannot be deleted and re-inserted partial
-- ---------------------------------------------------------------------------
-- The trigger keeps a required field from being blanked on UPDATE, but delete + insert
-- walked around it (the very failure the rule exists to prevent: a stale partial copy
-- replacing the good one). The row now goes only with its profile, by cascade.
drop policy coaching_profiles_delete_own on public.coaching_profiles;
revoke delete on public.coaching_profiles from authenticated;

-- ---------------------------------------------------------------------------
-- 6. New tables start closed
-- ---------------------------------------------------------------------------
-- Postgres gives anon/authenticated TRUNCATE (which ignores RLS), REFERENCES, TRIGGER
-- and MAINTAIN on every new postgres-owned table in public by default. A future
-- migration that forgot its own REVOKE would expose its table. Now a new table is
-- unreachable until it is granted something on purpose.
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated;
